try{ $$$TRACE("Connect to " _ ..ApplicationAddress) $$$TRACE("Connect to " _ ..TuxedoService) set objCdrTuxService = ##class(org.ihc.itf.cdr.drc.InitiateContextAndCdrTaskSearch).%New(..JavaGateway,..ApplicationAddress, ..TuxedoService, ..LogDirectory _"/" _$$$JobConfigName _".log", $$$ConfigTrace($$$JobConfigName))
$$$TRACE("Object name: " _ objCdrTuxService.%ClassName(1)) set reportDate = pRequest.StringValue $$$TRACE("ReportDate.. " _ reportDate) set pstatus=##class(IHC.ITF.ITFCOMMON.Utility).ItfLookup("IHC.ITF.Process.Bpl.InitiateDemogrXmlToCdrEmpiInvestigator.InitiateMpiProperties","INITIATE_HOST_USER",.retVal) set iniHostUser = retVal set pstatus=##class(IHC.ITF.ITFCOMMON.Utility).ItfLookup("IHC.ITF.Process.Bpl.InitiateDemogrXmlToCdrEmpiInvestigator.InitiateMpiProperties","INITIATE_HOST_NAME",.retVal) set iniHostName = retVal set pstatus=##class(IHC.ITF.ITFCOMMON.Utility).ItfLookup("IHC.ITF.Process.Bpl.InitiateDemogrXmlToCdrEmpiInvestigator.InitiateMpiProperties","INITIATE_HOST_PASSWORD",.retVal) set iniHostPwd = retVal set pstatus=##class(IHC.ITF.ITFCOMMON.Utility).ItfLookup("IHC.ITF.Process.Bpl.InitiateDemogrXmlToCdrEmpiInvestigator.InitiateMpiProperties","INITIATE_HOST_PORT",.retVal) set iniHostPort = retVal $$$TRACE("IniHostPort " _ iniHostPort)
