$$$TRACE("Output after invocation of OpCdrAndInitiateDemogrDrcDuplicates Java Method<" _ output _ ">")
Set tmpstream = ##class(%Stream.GlobalCharacter).%New() Do tmpstream.Write(output.toString()) Do tmpstream.%Save()
Set pResponse = ##class(Ens.StreamContainer).%New(tmpstream) set respMsg = pResponse.Stream.Read() $$$TRACE("OpCdrAndInitiateDemogrDrcDuplicates (Response): <" _ respMsg _ ">") if respMsg["CONNECTIONERROR"{ Set status = ##class(IHC.ITF.ITFCOMMON.Utility).RetryMsgError(..%ConfigName," Error while Connecting with Tuxedo Server. Retrying.. ") quit }
}catch err{ $$$LOGERROR("Exception while Creating Tuxedo Service: " _err.AsSystemError() _ " _ data: " _ err.Data _ "; code:" _ err.Code) Set status = ##class(IHC.ITF.ITFCOMMON.Utility).RetryMsgError(..%ConfigName," Exception while initializing Tuxedo Service: "_err.AsSystemError()_"::"_err.Data_"::"_err.Code) }
